    fun search(query: String): List<AsmaItem> {
        if (query.isBlank()) return names
        val q = query.trim().lowercase()
        return names.filter {
            it.nameTr.lowercase().contains(q) ||
            it.arabic.contains(q) ||
            it.meaningTr.lowercase().contains(q) ||
            it.number.toString() == q
        }
    }
